37	  const p: Record<string, string> = {};
38	  for (const part of fmt.formatToParts(new Date(ms))) p[part.type] = part.value;
39	  const hour = p.hour === "24" ? "00" : p.hour;
40	  return { date: `${p.year}-${p.month}-${p.day}`, time: `${hour}:${p.minute}` };
41	}
42	
43	function localDate(iso: string | undefined): string | undefined {
44	  if (!iso) return undefined;
45	  const lp = localParts(iso);
46	  return lp ? lp.date : undefined;
47	}
48	
49	function ms(iso: string | undefined): number {
50	  if (!iso) return NaN;
51	  return Date.parse(iso);
52	}
