58	interface Doc {
59	  item: FolioItem;
60	  enc: any | undefined;
61	  kind: string | undefined;
62	  encId: string;
63	  recordedMs: number;
64	  effectiveMs: number;
65	  /** When this document's decisions were made (discharge time for a discharge summary). */
66	  decisionTime: string;
67	  entries: [string, any][];
68	}
69	
70	function isObj(x: unknown): x is Record<string, any> {
71	  return typeof x === "object" && x !== null && !Array.isArray(x);
72	}
73	
74	function str(x: unknown): string | undefined {
75	  return typeof x === "string" && x.trim() !== "" ? x : undefined;
76	}
77	
78	function toDoc(item: FolioItem): Doc {
79	  const entries: [string, any][] = [];
80	  const payload = isObj(item.payload) ? item.payload : {};
81	  for (const k of Object.keys(payload)) {
82	    const e = payload[k];
83	    if (isObj(e) && typeof e.type === "string") entries.push([k, e]);
84	  }
85	  const encEntry = entries.find(([, e]) => e.type === "encounter");
86	  const enc = encEntry ? encEntry[1] : undefined;
87	  const kind = enc ? str(enc.document_kind) : undefined;
88	  let decisionTime = item.effective || item.recorded;
89	  if (kind === "discharge_summary") {
90	    decisionTime = str(enc?.discharged) ?? str(item.effective_end) ?? item.recorded;
91	  }
92	  if (!localParts(decisionTime)) decisionTime = item.recorded;
93	  return {
94	    item,
95	    enc,
96	    kind,
97	    encId: (enc && str(enc.encounter_id)) || `item:${item.id}`,
98	    recordedMs: ms(item.recorded),
99	    effectiveMs: ms(item.effective),
100	    decisionTime,
101	    entries,
102	  };
103	}
104	
105	function docOrder(a: Doc, b: Doc): number {
106	  const ra = isNaN(a.recordedMs) ? 0 : a.recordedMs;
107	  const rb = isNaN(b.recordedMs) ? 0 : b.recordedMs;
108	  if (ra !== rb) return ra - rb;
109	  const ea = isNaN(a.effectiveMs) ? 0 : a.effectiveMs;
110	  const eb = isNaN(b.effectiveMs) ? 0 : b.effectiveMs;
111	  if (ea !== eb) return ea - eb;
112	  return a.item.id < b.item.id ? -1 : a.item.id > b.item.id ? 1 : 0;
113	}
114	
115	function currentDocs(items: FolioItem[], asOf: string): Doc[] {
116	  const inScope = (Array.isArray(items) ? items : []).filter((it) => {
117	    if (!isObj(it) || typeof it.id !== "string") return false;
118	    const d = localDate(it.recorded);
119	    return !!d && d <= asOf;
120	  });
121	  const dead = new Set<string>();
122	  for (const it of inScope) {
123	    for (const list of [it.supersedes, it.retracts]) {
124	      if (!Array.isArray(list)) continue;
125	      for (const id of list) {
126	        if (typeof id === "string") dead.add(`${it.issuer}|${id}`);
127	      }
128	    }
129	  }
130	  return inScope
131	    .filter((it) => !dead.has(`${it.issuer}|${it.id}`))
132	    .map(toDoc)
133	    .sort(docOrder);
134	}
