187	function ingredientName(drugName: string): string | undefined {
188	  if (!drugName) return undefined;
189	  const words = drugName.trim().split(/\s+/);
190	  const kept: string[] = [];
191	  for (const w of words) {
192	    if (/\d/.test(w)) break;
193	    if (w.startsWith("(")) break;
194	    kept.push(w);
195	  }
196	  let out = kept
197	    .map((w) => w.toLowerCase().replace(/[,;]+$/, ""))
198	    .filter((w) => w && !SALT_OR_FORM.has(w));
199	  if (out.length === 0) return undefined;
200	  const joined = out.join(" ");
201	  if (BRANDS[joined]) return BRANDS[joined];
202	  if (out.length === 1 && BRANDS[out[0]]) return BRANDS[out[0]];
203	  return joined;
204	}
