208	  [/sglt-?2|sodium[- ]glucose/i, SGLT2],
209	  [/ace[- ]?inhibitor/i, new Set(["lisinopril", "enalapril", "ramipril", "benazepril", "captopril", "quinapril", "fosinopril", "perindopril", "trandolapril", "moexipril"])],
210	  [/\bstatin/i, new Set(["atorvastatin", "rosuvastatin", "simvastatin", "pravastatin", "lovastatin", "pitavastatin", "fluvastatin"])],
