218	type MedStatus = MedicationRow["status"];
219	
220	function medStatus(s: unknown): MedStatus | undefined {
221	  switch (s) {
222	    case "not_reconciled":
223	      return "unknown";
224	    case "continue":
225	    case "new":
226	    case "changed":
227	      return "active";
228	    case "held":
229	      return "held";
230	    case "stopped":
231	      return "stopped";
232	  }
233	  return undefined;
234	}
235	
236	function medKey(e: any): string | undefined {
237	  const rx = str(e.rxnorm_ingredient);
238	  if (rx) return `rx:${rx}`;
239	  const ing = ingredientName(str(e.drug_name) ?? "");
240	  if (ing) return `name:${ing}`;
241	  const dn = str(e.drug_name);
242	  return dn ? `name:${dn.toLowerCase()}` : undefined;
243	}
244	
245	function normDose(s: unknown): string {
246	  return typeof s === "string" ? s.toLowerCase().replace(/\s+/g, " ").trim() : "";
247	}
248	
249	function parseDose(text: unknown): MedicationRow["dose"] | undefined {
250	  if (typeof text !== "string") return undefined;
251	  const m = text.trim().match(/^(\d+(?:\.\d+)?|\.\d+)\s*([a-zA-Z\[\]]+)\.?$/);
252	  if (!m) return undefined;
253	  const value = Number(m[1]);
254	  if (!isFinite(value)) return undefined;
255	  const u = m[2].toLowerCase();
256	  let unit: NonNullable<MedicationRow["dose"]>["unit"] | undefined;
257	  if (u === "mg") unit = "mg";
258	  else if (u === "mcg" || u === "ug" || u === "µg") unit = "mcg";
259	  else if (["unit", "units", "u", "unt", "[iu]", "iu"].includes(u)) unit = "units";
260	  else if (u === "ml") unit = "mL";
261	  else if (["tab", "tabs", "tablet", "tablets"].includes(u)) unit = "tablet";
262	  if (!unit) return undefined;
263	  return { value, unit };
264	}
265	
266	function parseFrequency(sig: unknown): MedicationRow["frequency"] | undefined {
267	  if (typeof sig !== "string" || !sig.trim()) return undefined;
268	  const s = sig.toLowerCase();
269	  if (/\bprn\b|as needed|when needed|if needed/.test(s)) return "PRN";
270	  if (/\bqhs\b|nightly|at bedtime|\bbedtime\b|every night|each night|\bhs\b/.test(s)) return "QHS";
271	  if (/\bbid\b|twice (a |per )?day|twice daily|two times (a |per )?day|every 12 hours|\bq12h\b/.test(s)) return "BID";
272	  if (/\btid\b|three times (a |per )?day|three times daily|every 8 hours|\bq8h\b/.test(s)) return "TID";
273	  if (/\bqw\b|weekly|once (a |per )?week|every week/.test(s)) return "QW";
274	  if (/\bqd\b|\bdaily\b|once (a |per )?day|every day|every morning|each morning|\bqam\b|every 24 hours|\bq24h\b/.test(s)) {
275	    if (/every other day/.test(s)) return "other";
276	    return "QD";
277	  }
278	  if (/\bqid\b|four times|every \d+ (hours|days|weeks)|\bq\d+h\b|every other|monthly|\bmonth\b/.test(s)) return "other";
279	  return undefined;
280	}
281	
282	function stopReason(text: string | undefined, adverse: boolean): MedicationRow["stop_reason"] | undefined {
283	  if (adverse) return "adverse_reaction";
284	  if (!text) return undefined;
285	  const t = text.toLowerCase();
286	  if (/adverse|side effect|reaction|intoleran|ketoacidosis|\bdka\b|lactic acidosis|angioedema|rash|hives|cough|allerg/.test(t)) return "adverse_reaction";
287	  if (/ineffective|not effective|not working|inadequate|insufficient/.test(t)) return "ineffective";
288	  if (/replaced|switch|changed to|instead of|in place of|substitut/.test(t)) return "therapy_changed";
289	  if (/course complete|completed course|course finished|completed/.test(t)) return "course_complete";
290	  if (/patient (declined|refused|preference|request|choice|chose|wishes)|declined by patient/.test(t)) return "patient_choice";
291	  return undefined;
292	}
293	
294	interface AdverseLink {
295	  ingredient: string;
296	  rxnorm?: string;
297	  encId: string;
298	}
299	
300	function buildMedications(docs: Doc[], adverse: AdverseLink[]): MedicationRow[] {
301	  const medDocs = docs.filter((d) => d.entries.some(([, e]) => e.type === "home_med"));
302	  if (medDocs.length === 0) return [];
303	  // Snapshot: the latest encounter's latest discharge summary, else the latest document with a list.
304	  const latest = docs[docs.length - 1];
305	  let snap: Doc;
306	  const ds = docs.filter((d) => d.encId === latest.encId && d.kind === "discharge_summary");
307	  if (ds.length > 0) snap = ds[ds.length - 1];
308	  else {
309	    const sameEnc = medDocs.filter((d) => d.encId === latest.encId);
310	    snap = sameEnc.length > 0 ? sameEnc[sameEnc.length - 1] : medDocs[medDocs.length - 1];
311	  }
312	  const snapIdx = docs.indexOf(snap);
313	
314	  const rank: Record<MedStatus, number> = { active: 4, held: 3, unknown: 2, stopped: 1 };
315	  const chosen = new Map<string, { id: string; e: any; st: MedStatus }>();
316	  for (const [id, e] of snap.entries) {
317	    if (e.type !== "home_med") continue;
318	    const st = medStatus(e.status);
319	    const key = medKey(e);
320	    if (!st || !key || !str(e.drug_name)) continue;
321	    const prev = chosen.get(key);
322	    if (!prev || rank[st] > rank[prev.st]) chosen.set(key, { id, e, st });
323	  }
324	
325	  const rows: MedicationRow[] = [];
326	  for (const [key, { id, e, st }] of chosen) {
327	    const dose = normDose(e.dose_text);
328	    const evidence: Evidence = [{ item_id: snap.item.id, entry_id: id }];
329	    let since: PartialDate | undefined;
330	    let reasonText = str(e.instructions);
331	
332	    const lineIn = (d: Doc): [string, any] | undefined => {
333	      const cands = d.entries.filter(([, x]) => x.type === "home_med" && medKey(x) === key);
334	      return cands.find(([, x]) => normDose(x.dose_text) === dose) ?? cands[0];
335	    };
336	
337	    if (st === "held" || st === "stopped") {
338	      let start: Doc = snap;
339	      let startEntry = id;
340	      for (let i = snapIdx - 1; i >= 0; i--) {
341	        const l = lineIn(docs[i]);
342	        if (!l) {
343	          if (docs[i].entries.some(([, x]) => x.type === "home_med")) break;
344	          continue; // document without a medication list says nothing
345	        }
346	        if (medStatus(l[1].status) !== st || normDose(l[1].dose_text) !== dose) break;
347	        start = docs[i];
348	        startEntry = l[0];
349	        if (!reasonText) reasonText = str(l[1].instructions);
350	      }
351	      since = localDate(start.decisionTime);
352	      if (start !== snap) evidence.push({ item_id: start.item.id, entry_id: startEntry });
353	    } else if (st === "active") {
354	      if (e.status === "new" || e.status === "changed") since = localDate(snap.decisionTime);
355	      else {
356	        let earliest: Doc = snap;
357	        let earliestEntry = id;
358	        for (let i = snapIdx - 1; i >= 0; i--) {
359	          const l = lineIn(docs[i]);
360	          if (!l) {
361	            if (docs[i].entries.some(([, x]) => x.type === "home_med")) break;
362	            continue;
363	          }
364	          const pst = medStatus(l[1].status);
365	          if (pst === "active" && normDose(l[1].dose_text) === dose) {
366	            earliest = docs[i];
367	            earliestEntry = l[0];
368	            if (l[1].status === "new" || l[1].status === "changed") {
369	              since = localDate(docs[i].decisionTime);
370	              break;
371	            }
372	            continue;
373	          }
374	          if (pst === "held" || pst === "stopped" || (pst === "active" && normDose(l[1].dose_text) !== dose)) {
375	            since = localDate(earliest.decisionTime); // resumed or re-dosed here
376	          }
377	          break;
378	        }
379	        if (since && earliest !== snap) evidence.push({ item_id: earliest.item.id, entry_id: earliestEntry });
380	      }
381	    }
382	
383	    const drugName = str(e.drug_name) as string;
384	    const ingredient = ingredientName(drugName);
385	    const row: MedicationRow = {
386	      drug_name: drugName,
387	      status: st,
388	      patient_reported: false,
389	      evidence,
390	    };
391	    if (ingredient) row.ingredient = ingredient;
392	    const rx = str(e.rxnorm_ingredient);
393	    if (rx) row.rxnorm_ingredient = rx;
394	    if (since) row.status_since = since;
395	    const d = parseDose(e.dose_text);
396	    if (d) row.dose = d;
397	    const f = parseFrequency(e.sig);
398	    if (f) row.frequency = f;
399	    if (st === "stopped") {
400	      const adv = adverse.some((a) => (rx && a.rxnorm === rx) || (ingredient && a.ingredient === ingredient));
401	      const r = stopReason(reasonText, adv);
402	      if (r) row.stop_reason = r;
403	    }
404	    if ((st === "held" || st === "stopped") && reasonText) row.status_reason_text = reasonText;
405	    rows.push(sortKeys(row));
406	  }
407	  rows.sort((a, b) => (a.ingredient ?? a.drug_name).localeCompare(b.ingredient ?? b.drug_name));
408	  return rows;
409	}
