412	// Adverse drug effects recorded as diagnoses
413	// ─────────────────────────────────────────────────────────────────────────────────────────────────
414	
415	function isAdverseTCode(icd: string | undefined): boolean {
416	  if (!icd) return false;
417	  const c = icd.replace(/\./g, "").toUpperCase();
418	  const m = c.match(/^T(\d\d)/);
419	  if (!m) return false;
420	  const n = Number(m[1]);
421	  return n >= 36 && n <= 50 && c.length >= 6 && c[5] === "5";
422	}
423	
424	/** Drug phrase from "SGLT2 inhibitor-associated", "metformin-induced", "adverse effect of X". */
425	function drugPhrase(text: string): string | undefined {
426	  let m = text.match(/([A-Za-z0-9][A-Za-z0-9 \-\/]*?)[- ](?:associated|induced)\b/i);
427	  if (m) {
428	    const words = m[1].trim().split(/[\s,]+/);
429	    // keep the trailing words that name the drug (stop at a comma-separated condition prefix)
430	    const tail = m[1].split(",").pop()!.trim();
431	    return tail || words[words.length - 1];
432	  }
433	  m = text.match(/adverse (?:effect|reaction) (?:of|to|from)\s+([^,;()]+)/i);
434	  if (m) return m[1].trim();
435	  return undefined;
436	}
437	
438	interface DrugResolution {
439	  substance: string;
440	  rxnorm?: string;
441	  evidence: Evidence;
442	}
443	
444	function resolveDrug(phrase: string, encId: string, docs: Doc[]): DrugResolution {
445	  const lines: { ing: string; rx?: string; ev: { item_id: string; entry_id: string } }[] = [];
446	  const encDocs = docs.filter((d) => d.encId === encId);
447	  for (const d of encDocs.length ? encDocs : docs) {
448	    for (const [id, e] of d.entries) {
449	      if (e.type !== "home_med" && e.type !== "inpatient_med") continue;
450	      const ing = ingredientName(str(e.drug_name) ?? "");
451	      if (!ing) continue;
452	      lines.push({ ing, rx: str(e.rxnorm_ingredient), ev: { item_id: d.item.id, entry_id: id } });
453	    }
454	  }
455	  const p = phrase.toLowerCase().trim();
456	  let matcher: ((ing: string) => boolean) | undefined;
457	  for (const [re, set] of DRUG_CLASSES) {
458	    if (re.test(p)) {
459	      matcher = (ing) => set.has(ing);
460	      break;
461	    }
462	  }
463	  if (!matcher) {
464	    const direct = BRANDS[p] ?? ingredientName(p) ?? p;
465	    matcher = (ing) => ing === direct || ing.split(" ").includes(direct);
466	  }
467	  const hits = lines.filter((l) => matcher!(l.ing));
468	  const ings = Array.from(new Set(hits.map((h) => h.ing)));
469	  if (ings.length === 1) {
470	    const h = hits.filter((x) => x.ing === ings[0]);
471	    const rx = h.find((x) => x.rx)?.rx;
472	    return { substance: ings[0], rxnorm: rx, evidence: [h[h.length - 1].ev] };
473	  }
474	  const isClass = DRUG_CLASSES.some(([re]) => re.test(p));
475	  return { substance: isClass ? phrase.trim() : (BRANDS[p] ?? p), evidence: [] };
476	}
