482	interface CondEntry {
483	  doc: Doc;
484	  docIdx: number;
485	  id: string;
486	  kind: "diagnosis" | "history";
487	  label: string;
488	  icd?: string;
489	  rdx?: string;
490	  status: "working" | "ruled_out" | "active" | "resolved";
491	  onsetText?: string;
492	}
