494	function normLabel(s: string): string {
495	  return s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
496	}
497	
498	function parseOnset(text: string | undefined): ProblemRow["onset"] | undefined {
499	  if (!text) return undefined;
500	  const t = text.trim();
501	  let m = t.match(/^(\d{4})$/);
502	  if (m) return { value: m[1], precision: "year" };
503	  m = t.match(/^(\d{4})-(\d{2})$/);
504	  if (m) return { value: `${m[1]}-${m[2]}`, precision: "month" };
505	  m = t.match(/^(\d{4})-(\d{2})-(\d{2})$/);
506	  if (m) return { value: t, precision: "day" };
507	  m = t.match(/^(\d{1,2})\/(\d{4})$/);
508	  if (m && Number(m[1]) >= 1 && Number(m[1]) <= 12) return { value: `${m[2]}-${m[1].padStart(2, "0")}`, precision: "month" };
509	  m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
510	  if (m && Number(m[1]) <= 12 && Number(m[2]) <= 31)
511	    return { value: `${m[3]}-${m[1].padStart(2, "0")}-${m[2].padStart(2, "0")}`, precision: "day" };
512	  return undefined;
513	}
514	
515	function ckdStage(text: string, icd: string | undefined): ProblemRow["ckd_stage"] | undefined {
516	  if (icd) {
517	    const c = icd.toUpperCase();
518	    if (c === "N18.1") return "G1";
519	    if (c === "N18.2") return "G2";
520	    if (c === "N18.31") return "G3a";
521	    if (c === "N18.32") return "G3b";
522	    if (c === "N18.4") return "G4";
523	    if (c === "N18.5" || c === "N18.6") return "G5";
524	  }
525	  const t = text.toLowerCase();
526	  let m = t.match(/\bg\s?(1|2|3a|3b|4|5)\b/);
527	  if (!m) m = t.match(/stage\s*(1|2|3a|3b|4|5|i{1,3}a?b?|iv|v)\b/);
528	  if (!m) m = t.match(/\bckd\s*(1|2|3a|3b|4|5)\b/);
529	  if (!m) return undefined;
530	  const roman: Record<string, string> = { i: "1", ii: "2", iiia: "3a", iiib: "3b", iv: "4", v: "5" };
531	  const v = roman[m[1]] ?? m[1];
532	  const map: Record<string, ProblemRow["ckd_stage"]> = { "1": "G1", "2": "G2", "3a": "G3a", "3b": "G3b", "4": "G4", "5": "G5" };
533	  return map[v];
534	}
