545	function buildProblems(docs: Doc[], adverseOut: AllergyIntoleranceRow[], adverseLinks: AdverseLink[]): ProblemRow[] {
546	  const entries: CondEntry[] = [];
547	  docs.forEach((doc, docIdx) => {
548	    for (const [id, e] of doc.entries) {
549	      if (e.type === "diagnosis") {
550	        const label = str(e.label) ?? str(e.riverside_dx?.name);
551	        const status = e.status;
552	        if (!label || !["working", "ruled_out", "active", "resolved"].includes(status)) continue;
553	        entries.push({
554	          doc, docIdx, id, kind: "diagnosis", label,
555	          icd: str(e.icd10cm), rdx: isObj(e.riverside_dx) ? str(e.riverside_dx.code) : undefined, status,
556	        });
557	      } else if (e.type === "history") {
558	        const label = str(e.condition);
559	        if (!label) continue;
560	        const resolved = /\b(resolved|history of|h\/o|remote)\b/i.test(label);
561	        entries.push({
562	          doc, docIdx, id, kind: "history", label, icd: str(e.icd10cm),
563	          status: resolved ? "resolved" : "active", onsetText: str(e.onset_text),
564	        });
565	      }
566	    }
567	  });
568	
569	  // Adverse drug effects coded as T-codes: allergy rows, not problems.
570	  const advEntries = entries.filter((c) => isAdverseTCode(c.icd));
571	  const condEntries = entries.filter((c) => !isAdverseTCode(c.icd));
572	
573	  // Drug-associated illnesses (riverside_dx / label naming a drug): the illness stays a problem, and the
574	  // drug gets an adverse-reaction row.
575	  const assocEntries = condEntries.filter((c) => c.kind === "diagnosis" && drugPhrase(c.label));
576	  handleAdverse([...advEntries.map((c) => ({ c, tcode: true })), ...assocEntries.map((c) => ({ c, tcode: false }))], docs, adverseOut, adverseLinks);
577	
578	  // Group entries into conditions.
579	  const groups: CondEntry[][] = [];
580	  const byRdx = new Map<string, CondEntry[]>();
581	  for (const c of condEntries) {
582	    if (c.rdx) {
583	      let g = byRdx.get(c.rdx);
584	      if (!g) {
585	        g = [];
586	        byRdx.set(c.rdx, g);
587	        groups.push(g);
588	      }
589	      g.push(c);
590	    }
591	  }
592	  const byIcd = new Map<string, CondEntry[]>();
593	  const byLabel = new Map<string, CondEntry[]>();
594	  const pending = condEntries.filter((c) => !c.rdx);
595	  for (const c of pending) {
596	    let g: CondEntry[] | undefined;
597	    if (c.icd) {
598	      const icd = c.icd.toUpperCase();
599	      const rdxGroups = Array.from(byRdx.values()).filter((gg) => gg.some((x) => x.icd && x.icd.toUpperCase() === icd));
600	      if (rdxGroups.length === 1) g = rdxGroups[0];
601	      else g = byIcd.get(icd);
602	      if (!g) {
603	        g = byLabel.get(normLabel(c.label));
604	        if (!g) {
605	          g = [];
606	          groups.push(g);
607	        }
608	        byIcd.set(icd, g);
609	      }
610	    } else {
611	      const nl = normLabel(c.label);
612	      g = byLabel.get(nl);
613	      if (!g) {
614	        for (const gg of groups) {
615	          if (gg.some((x) => normLabel(x.label) === nl)) {
616	            g = gg;
617	            break;
618	          }
619	        }
620	      }
621	      if (!g) {
622	        g = [];
623	        groups.push(g);
624	      }
625	    }
626	    g.push(c);
627	    byLabel.set(normLabel(c.label), g);
628	  }
629	
630	  const rows: ProblemRow[] = [];
631	  for (const g of groups) {
632	    g.sort((a, b) => a.docIdx - b.docIdx);
633	    const dx = g.filter((c) => c.kind === "diagnosis");
634	    const decisive = dx.filter((c) => c.status !== "working");
635	    let status: "active" | "resolved" | undefined;
636	    let basis: CondEntry[];
637	    if (decisive.length > 0) {
638	      const last = decisive[decisive.length - 1];
639	      if (last.status === "ruled_out") {
640	        // A later history line can reassert it.
641	        const laterHist = g.filter((c) => c.kind === "history" && c.docIdx > last.docIdx);
642	        if (laterHist.length === 0) continue;
643	        status = laterHist[laterHist.length - 1].status as "active" | "resolved";
644	        basis = laterHist;
645	      } else {
646	        status = last.status as "active" | "resolved";
647	        basis = decisive.filter((c) => c.status !== "ruled_out");
648	      }
649	    } else {
650	      const hist = g.filter((c) => c.kind === "history");
651	      if (hist.length === 0) continue; // only ever suspected
652	      status = hist[hist.length - 1].status as "active" | "resolved";
653	      basis = hist;
654	    }
655	    const latest = basis[basis.length - 1];
656	    const row: ProblemRow = { condition: latest.label, status, evidence: [] };
657	    const withIcd = basis.filter((c) => c.icd);
658	    if (withIcd.length) row.icd10cm = withIcd[withIcd.length - 1].icd;
659	    const hist = g.filter((c) => c.kind === "history" && c.onsetText);
660	    for (let i = hist.length - 1; i >= 0; i--) {
661	      const o = parseOnset(hist[i].onsetText);
662	      if (o) {
663	        row.onset = o;
664	        break;
665	      }
666	    }
667	    if (g.some((c) => isCkd(c.label, c.icd))) {
668	      // Prefer clinician diagnoses over unverified history lines; latest first.
669	      const ordered = [...g.filter((c) => c.kind === "history"), ...g.filter((c) => c.kind === "diagnosis" && c.status !== "ruled_out")];
670	      for (let i = ordered.length - 1; i >= 0; i--) {
671	        const s = ckdStage(ordered[i].label, ordered[i].icd);
672	        if (s) {
673	          row.ckd_stage = s;
674	          break;
675	        }
676	      }
677	      for (let i = ordered.length - 1; i >= 0; i--) {
678	        const a = albuminuria(ordered[i].label);
679	        if (a) {
680	          row.albuminuria = a;
681	          break;
682	        }
683	      }
684	    }
685	    const seen = new Set<string>();
686	    for (const c of [...g].reverse()) {
687	      if (c.status === "ruled_out" || (c.kind === "diagnosis" && c.status === "working")) continue;
688	      const k = `${c.doc.item.id}|${c.id}`;
689	      if (seen.has(k)) continue;
690	      seen.add(k);
691	      row.evidence.push({ item_id: c.doc.item.id, entry_id: c.id });
692	    }
693	    if (row.evidence.length === 0) row.evidence.push({ item_id: latest.doc.item.id, entry_id: latest.id });
694	    rows.push(sortKeys(row));
695	  }
696	  return rows;
697	}
