703	const ALLERGIC = /hives|urticaria|rash|angioedema|anaphyla|bronchospasm|wheez|throat (swelling|closing)|swelling|itch|prurit|stevens|sjs|\bten\b|dress|eczema|allergic/i;
704	const SERIOUS_ADVERSE = /ketoacidosis|\bdka\b|lactic acidosis|pancreatitis|hepatotox|liver (injury|failure)|kidney injury|renal failure|\baki\b|agranulocytosis|rhabdomyolysis|hyperkalemia|hyponatremia|bleed|hemorrhage|qt prolong|torsade|seizure|hypoglycemi|neutropenia|thrombocytopenia|myopathy/i;
705	const HIGH_CRIT = /anaphyla|angioedema|stevens|sjs|toxic epidermal|ketoacidosis|\bdka\b|lactic acidosis|throat (swelling|closing)|bronchospasm/i;
706	
707	function classifyReaction(reaction: string | undefined): AllergyIntoleranceRow["type"] {
708	  if (!reaction) return "allergy";
709	  if (ALLERGIC.test(reaction)) return "allergy";
710	  if (SERIOUS_ADVERSE.test(reaction)) return "adverse_reaction";
711	  return "intolerance";
712	}
