714	function handleAdverse(
715	  list: { c: CondEntry; tcode: boolean }[],
716	  docs: Doc[],
717	  out: AllergyIntoleranceRow[],
718	  links: AdverseLink[],
719	): void {
720	  // Only established diagnoses count (not working, not ruled out); latest status per entry group wins.
721	  const latestByKey = new Map<string, CondEntry>();
722	  const allByKey = new Map<string, CondEntry[]>();
723	  for (const { c, tcode } of list) {
724	    if (c.kind === "diagnosis" && c.status === "working") continue;
725	    const phrase = drugPhrase(c.label) ?? (tcode ? c.label : undefined);
726	    if (!phrase) continue;
727	    const res = resolveDrug(phrase, c.doc.encId, docs);
728	    const key = res.rxnorm ? `rx:${res.rxnorm}` : `s:${res.substance.toLowerCase()}`;
729	    const prev = latestByKey.get(key);
730	    if (!prev || c.docIdx >= prev.docIdx) latestByKey.set(key, c);
731	    const all = allByKey.get(key) ?? [];
732	    all.push(c);
733	    allByKey.set(key, all);
734	  }
735	  for (const [key, c] of latestByKey) {
736	    if (c.status === "ruled_out") continue;
737	    const phrase = drugPhrase(c.label) ?? c.label;
738	    const res = resolveDrug(phrase, c.doc.encId, docs);
739	    const all = (allByKey.get(key) ?? []).filter((x) => x.status !== "ruled_out").sort((a, b) => a.docIdx - b.docIdx);
740	    let reaction = c.label;
741	    // Name the reaction by the illness (strip the drug attribution).
742	    const stripped = c.label
743	      .replace(/,?\s*[A-Za-z0-9 \-\/]*?[- ](associated|induced|related)\b/i, "")
744	      .replace(/\s*,\s*$/, "")
745	      .trim();
746	    if (stripped && stripped !== c.label) reaction = stripped;
747	    const first = all[0] ?? c;
748	    const enc = first.doc.enc;
749	    const onsetDate = localDate(str(enc?.arrived) ?? str(enc?.admitted) ?? first.doc.item.effective);
750	    const row: AllergyIntoleranceRow = {
751	      substance: res.substance,
752	      type: "adverse_reaction",
753	      reaction,
754	      criticality: HIGH_CRIT.test(c.label) ? "high" : "unknown",
755	      evidence: [
756	        ...all.reverse().map((x) => ({ item_id: x.doc.item.id, entry_id: x.id })),
757	        ...res.evidence,
758	      ],
759	    };
760	    if (res.rxnorm) row.rxnorm_ingredient = res.rxnorm;
761	    if (onsetDate && onsetDate.length === 10) row.onset = { value: onsetDate, precision: "day" };
762	    out.push(row);
763	    links.push({ ingredient: res.substance.toLowerCase(), rxnorm: res.rxnorm, encId: c.doc.encId });
764	  }
765	}
