767	function buildAllergies(docs: Doc[], adverseRows: AllergyIntoleranceRow[]): AllergyIntoleranceRow[] {
768	  const rows: AllergyIntoleranceRow[] = [];
769	  const listDocs = docs.filter((d) => d.entries.some(([, e]) => e.type === "allergy"));
770	  if (listDocs.length > 0) {
771	    const snap = listDocs[listDocs.length - 1];
772	    const byKey = new Map<string, AllergyIntoleranceRow>();
773	    for (const [id, e] of snap.entries) {
774	      if (e.type !== "allergy") continue;
775	      const sub = str(e.substance);
776	      if (!sub) continue;
777	      if (/^(nkda|nka|no known (drug )?allergies)$/i.test(sub.trim())) continue;
778	      const rx = str(e.rxnorm_ingredient);
779	      const reaction = str(e.reaction);
780	      const ing = rx ? ingredientName(sub) ?? sub.toLowerCase() : BRANDS[sub.toLowerCase()] ?? sub;
781	      const type = classifyReaction(reaction);
782	      let crit: AllergyIntoleranceRow["criticality"] =
783	        e.severity === "severe" ? "high" : e.severity === "mild" ? "low" : "unknown";
784	      if (reaction && HIGH_CRIT.test(reaction)) crit = "high";
785	      const key = rx ? `rx:${rx}` : `s:${ing.toLowerCase()}`;
786	      const prev = byKey.get(key);
787	      if (prev) {
788	        if (reaction && !(prev.reaction ?? "").split("; ").includes(reaction))
789	          prev.reaction = prev.reaction ? `${prev.reaction}; ${reaction}` : reaction;
790	        if (crit === "high" || (prev.criticality === "unknown" && crit === "low")) prev.criticality = crit;
791	        if (type === "allergy" || (type === "adverse_reaction" && prev.type === "intolerance")) prev.type = type;
792	        prev.evidence.push({ item_id: snap.item.id, entry_id: id });
793	        continue;
794	      }
795	      const row: AllergyIntoleranceRow = {
796	        substance: ing,
797	        type,
798	        criticality: crit,
799	        evidence: [{ item_id: snap.item.id, entry_id: id }],
800	      };
801	      if (rx) row.rxnorm_ingredient = rx;
802	      if (reaction) row.reaction = reaction;
803	      byKey.set(key, row);
804	      rows.push(row);
805	    }
806	  }
807	  for (const a of adverseRows) {
808	    const match = rows.find(
809	      (r) => (a.rxnorm_ingredient && r.rxnorm_ingredient === a.rxnorm_ingredient) || r.substance.toLowerCase() === a.substance.toLowerCase(),
810	    );
811	    if (match) {
812	      match.evidence.push(...a.evidence);
813	      if (!match.reaction && a.reaction) match.reaction = a.reaction;
814	      if (!match.onset && a.onset) match.onset = a.onset;
815	      if (match.criticality !== "high" && a.criticality === "high") match.criticality = "high";
816	      if (!match.rxnorm_ingredient && a.rxnorm_ingredient) match.rxnorm_ingredient = a.rxnorm_ingredient;
817	      continue;
818	    }
819	    rows.push(a);
820	  }
821	  return rows.map(sortKeys);
822	}
