867	function analyteFor(test: any, specimen: string): Analyte | undefined {
868	  const name = String(test?.name ?? "");
869	  const loinc = str(test?.loinc);
870	  const local = String(test?.local_code ?? "").toUpperCase();
871	  let a: Analyte | undefined = (loinc && LOINC_MAP[loinc]) || LOCAL_MAP[local];
872	  if (!a && !loinc) {
873	    const n = name.toLowerCase();
874	    if (/beta[- ]?hydroxybutyrate|\bbhb\b/.test(n)) a = "bhb";
875	    else if (/^creatinine\b/.test(n) && !/urine|clearance/.test(n)) a = "creatinine";
876	    else if (/\begfr\b/.test(n)) a = "egfr";
877	    else if (/lipase/.test(n)) a = "lipase";
878	    else if (/troponin i\b/.test(n)) a = "troponin";
879	    else if (/hemoglobin a1c|\bhba1c\b|\ba1c\b/.test(n)) a = "a1c";
880	    else if (/albumin.*creatinine.*ratio|\buacr\b/.test(n)) a = "uacr";
881	  }
882	  if (!a) return undefined;
883	  const n = name.toLowerCase();
884	  const sp = specimen.toLowerCase();
885	  if (a === "troponin" && /troponin t\b|tnt/.test(n)) return undefined;
886	  if (a === "glucose" && (/poc|point[- ]of[- ]care|meter|fingerstick|capillary/.test(n) || /capillary|fingerstick/.test(sp))) return undefined;
887	  if (a === "glucose" && /urine|csf|fluid/.test(sp)) return undefined;
888	  if ((a === "creatinine" || a === "potassium" || a === "sodium" || a === "bun") && /urine/.test(sp + " " + n)) return undefined;
889	  if (a === "ph" && /urine/.test(sp + " " + n)) return undefined;
890	  return a;
891	}
