904	/** Factor converting the reported unit to the analyte's unit, or undefined if unknown. */
905	function unitFactor(a: Analyte, unit: string | undefined, value: number): ((v: number) => number) | undefined {
906	  const u = normUnit(unit);
907	  const id = (v: number) => v;
908	  switch (a) {
909	    case "ph":
910	      return u === "" || u === "[ph]" || u === "ph" ? id : undefined;
911	    case "egfr":
912	      return /^ml\/min(\/1\.73m2|\/\{1\.73_m2\}|\/1\.73m\^2|\/1\.73sqm|\/1\.73m²)?$/.test(u) ? id : undefined;
913	    case "creatinine":
914	      if (u === "mg/dl") return id;
915	      if (u === "umol/l") return (v) => v / 88.42;
916	      return undefined;
917	    case "potassium": case "sodium": case "chloride": case "bicarbonate": case "anion_gap": case "bhb":
918	      return u === "mmol/l" || u === "meq/l" ? id : undefined;
919	    case "bun":
920	      return u === "mg/dl" ? id : u === "mmol/l" ? (v) => v * 2.801 : undefined;
921	    case "glucose":
922	      return u === "mg/dl" ? id : u === "mmol/l" ? (v) => v * 18.016 : undefined;
923	    case "a1c":
924	      return u === "%" || u === "%hb" || u === "%{hb}" ? id : u === "mmol/mol" ? (v) => v / 10.929 + 2.15 : undefined;
925	    case "uacr":
926	      return u === "mg/g" || u === "mg/g{creat}" || u === "ug/mg" ? id : u === "mg/mmol" ? (v) => v * 8.84 : undefined;
927	    case "platelets": case "wbc":
928	      if (["10*3/ul", "k/ul", "10^3/ul", "x10^3/ul", "x10e3/ul", "10*9/l", "10^9/l", "x10^9/l", "thou/ul", "k/mm3", "10*3/mm3"].includes(u)) return id;
929	      if (u === "/ul" || u === "cells/ul" || u === "/mm3") return (v) => v / 1000;
930	      return undefined;
931	    case "hemoglobin":
932	      return u === "g/dl" ? id : u === "g/l" ? (v) => v / 10 : undefined;
933	    case "pco2":
934	      return u === "mmhg" || u === "mm[hg]" ? id : u === "kpa" ? (v) => v * 7.50062 : undefined;
935	    case "lipase":
936	      return u === "u/l" || u === "iu/l" ? id : undefined;
937	    case "troponin":
938	      if (u === "ng/ml" || u === "ug/l") return id;
939	      if (u === "ng/l" || u === "pg/ml") return (v) => v / 1000;
940	      return undefined;
941	    case "cholesterol": case "hdl": case "ldl":
942	      return u === "mg/dl" ? id : u === "mmol/l" ? (v) => v * 38.67 : undefined;
943	    case "triglycerides":
944	      return u === "mg/dl" ? id : u === "mmol/l" ? (v) => v * 88.57 : undefined;
945	  }
946	  return undefined;
947	}
