949	function parseValue(text: unknown): { value: number; comparator?: LabResultRow["comparator"] } | undefined {
950	  if (typeof text === "number" && isFinite(text)) return { value: text };
951	  if (typeof text !== "string") return undefined;
952	  const m = text.trim().replace(/,/g, "").match(/^(<=|>=|≤|≥|<|>)?\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+))$/);
953	  if (!m) return undefined;
954	  const value = Number(m[2]);
955	  if (!isFinite(value)) return undefined;
956	  const c = m[1] === "≤" ? "<=" : m[1] === "≥" ? ">=" : (m[1] as LabResultRow["comparator"] | undefined);
957	  return c ? { value, comparator: c } : { value };
958	}
