965	function egfrEquation(name: string, loinc: string | undefined, collected: string): LabResultRow["egfr_equation"] {
966	  const n = name.toLowerCase();
967	  if (/mdrd/.test(n)) return "mdrd";
968	  if (/ckd[- ]?epi/.test(n) || /2021|2009/.test(n)) {
969	    if (/2021|race[- ]free|without race/.test(n)) return "ckd-epi-2021";
970	    if (/2009/.test(n)) return "ckd-epi-2009";
971	  }
972	  if (loinc === "98979-8" || loinc === "98980-6") return "ckd-epi-2021";
973	  if (loinc === "62238-1" || loinc === "88293-6" || loinc === "88294-4") return "ckd-epi-2009";
974	  if (loinc === "33914-3" || loinc === "48642-3" || loinc === "48643-1" || loinc === "50044-7" || loinc === "77147-7") return "mdrd";
975	  const d = localDate(collected);
976	  if (d && d >= "2023-01-01") return "ckd-epi-2021"; // Riverside: CKD-EPI 2021 for all results since 2023
977	  return "unknown";
978	}
