980	function isRaceVariant(name: string, loinc: string | undefined): boolean {
981	  if (loinc === "48643-1" || loinc === "88293-6") return true;
982	  const n = name.toLowerCase();
983	  if (/non[- ]?(african|black|aa\b)/.test(n)) return false;
984	  return /african[- ]american|\bblack\b|\baa\b/.test(n);
