986	
987	const STATUS_RANK: Record<string, number> = { preliminary: 1, final: 2, corrected: 3 };
988	
989	interface LabCopy {
990	  doc: Doc;
991	  docIdx: number;
992	  entryId: string;
993	  status: string;
994	  value: any;
995	  collected: string;
