1000	function buildLabs(docs: Doc[]): LabResultRow[] {
1001	  const copies = new Map<string, LabCopy[]>();
1002	  const add = (key: string, c: LabCopy) => {
1003	    const l = copies.get(key) ?? [];
1004	    l.push(c);
1005	    copies.set(key, l);
1006	  };
1007	  docs.forEach((doc, docIdx) => {
1008	    for (const [id, e] of doc.entries) {
1009	      if (e.type === "result" && isObj(e.test)) {
1010	        const acc = str(e.accession) ?? `${doc.item.id}:${id}`;
1011	        add(`${acc}|${e.test.local_code ?? e.test.name}`, {
1012	          doc, docIdx, entryId: id, status: e.status, value: e,
1013	          collected: e.collected, specimen: String(e.specimen ?? ""), accession: acc,
1014	        });
1015	      } else if (e.type === "panel" && Array.isArray(e.components)) {
1016	        const acc = str(e.accession) ?? `${doc.item.id}:${id}`;
1017	        for (const comp of e.components) {
1018	          if (!isObj(comp) || !isObj(comp.test)) continue;
1019	          add(`${acc}|${comp.test.local_code ?? comp.test.name}`, {
1020	            doc, docIdx, entryId: id, status: e.status, value: comp,
1021	            collected: e.collected, specimen: String(e.specimen ?? ""), accession: acc,
1022	          });
1023	        }
1024	      }
