1026	  });
1027	
1028	  const rows: LabResultRow[] = [];
1029	  for (const list of copies.values()) {
1030	    const best = [...list].sort(
1031	      (a, b) => (STATUS_RANK[b.status] ?? 0) - (STATUS_RANK[a.status] ?? 0) || b.docIdx - a.docIdx,
1032	    )[0];
1033	    if (!best || !(best.status in STATUS_RANK)) continue;
1034	    const test = best.value.test;
1035	    const analyte = analyteFor(test, best.specimen);
1036	    if (!analyte) continue;
1037	    if (!best.collected || isNaN(Date.parse(best.collected))) continue;
1038	    const name = String(test.name ?? "");
1039	    const loinc = str(test.loinc);
1040	    if (analyte === "egfr" && isRaceVariant(name, loinc)) continue;
1041	    const pv = parseValue(best.value.value);
1042	    if (!pv) continue;
1043	    const conv = unitFactor(analyte, str(best.value.unit), pv.value);
1044	    if (!conv) continue;
1045	    let value = conv(pv.value);
1046	    if (conv(1) !== 1) value = round(value, analyte === "glucose" || analyte === "uacr" || analyte === "platelets" || analyte === "wbc" ? 1 : 3);
1047	    if (analyte === "glucose" && conv(1) !== 1) value = Math.round(value);
1048	    const row: LabResultRow = {
1049	      analyte,
1050	      value,
1051	      unit: UNIT[analyte],
1052	      collected: best.collected,
1053	      status: best.status === "preliminary" ? "preliminary" : "final",
1054	      evidence: [],
1055	    };
1056	    if (pv.comparator) row.comparator = pv.comparator;
1057	    if (analyte === "egfr") row.egfr_equation = egfrEquation(name, loinc, best.collected);
1058	    if (loinc) row.loinc = loinc;
1059	    const seen = new Set<string>();
1060	    for (const c of [best, ...[...list].sort((a, b) => b.docIdx - a.docIdx)]) {
1061	      const k = `${c.doc.item.id}|${c.entryId}`;
1062	      if (seen.has(k)) continue;
1063	      seen.add(k);
