1073	// Vitals
1074	// ─────────────────────────────────────────────────────────────────────────────────────────────────
1075	
1076	function num(x: unknown): number | undefined {
1077	  return typeof x === "number" && isFinite(x) ? x : undefined;
1078	}
1079	
1080	function buildVitals(docs: Doc[]): VitalRow[] {
1081	  interface V {
1082	    t: number;
1083	    taken: string;
1084	    encId: string;
1085	    sys?: number;
1086	    dia?: number;
1087	    hr?: number;
1088	    wt?: number;
1089	    ev: Evidence;
1090	  }
1091	  const byKey = new Map<string, V>();
1092	  for (const doc of docs) {
1093	    for (const [id, e] of doc.entries) {
1094	      if (e.type !== "vitals") continue;
1095	      const t = ms(e.taken);
1096	      if (isNaN(t)) continue;
1097	      const bp = isObj(e.bp) ? e.bp : undefined;
1098	      const sys = num(bp?.systolic_mmhg);
1099	      const dia = num(bp?.diastolic_mmhg);
1100	      const hr = num(e.heart_rate_bpm);
1101	      const wt = num(e.weight_kg);
1102	      if (sys === undefined && dia === undefined && hr === undefined && wt === undefined) continue;
1103	      const key = `${t}|${sys}|${dia}|${hr}|${wt}`;
1104	      const prev = byKey.get(key);
1105	      if (prev) {
1106	        prev.ev.push({ item_id: doc.item.id, entry_id: id });
1107	        continue;
1108	      }
1109	      byKey.set(key, { t, taken: e.taken, encId: doc.encId, sys, dia, hr, wt, ev: [{ item_id: doc.item.id, entry_id: id }] });
1110	    }
1111	  }
1112	  const sets = Array.from(byKey.values()).sort((a, b) => a.t - b.t);
1113	  const rows: VitalRow[] = [];
1114	  let last: { v: V; row: VitalRow } | undefined;
1115	  for (const v of sets) {
1116	    // A BP repeated within 30 minutes during the same stay is a repeat on the earlier set.
1117	    if (
1118	      last &&
1119	      last.v.encId === v.encId &&
1120	      v.t - last.v.t <= 30 * 60000 &&
1121	      v.t > last.v.t &&
1122	      v.sys !== undefined &&
1123	      last.row.systolic_mmhg !== undefined &&
1124	      last.row.repeat_systolic_mmhg === undefined
1125	    ) {
1126	      last.row.repeat_systolic_mmhg = v.sys;
1127	      if (v.dia !== undefined) last.row.repeat_diastolic_mmhg = v.dia;
1128	      if (last.row.pulse_bpm === undefined && v.hr !== undefined) last.row.pulse_bpm = v.hr;
1129	      if (last.row.weight_kg === undefined && v.wt !== undefined) last.row.weight_kg = round(v.wt, 1);
1130	      last.row.evidence.push(...v.ev);
1131	      continue;
1132	    }
1133	    const lp = localParts(v.taken);
1134	    if (!lp || !lp.time) continue;
1135	    const row: VitalRow = { setting: "hospital", local_time: `${lp.date}T${lp.time}`, evidence: v.ev };
1136	    if (v.sys !== undefined) row.systolic_mmhg = v.sys;
1137	    if (v.dia !== undefined) row.diastolic_mmhg = v.dia;
1138	    if (v.hr !== undefined) row.pulse_bpm = v.hr;
1139	    if (v.wt !== undefined) row.weight_kg = round(v.wt, 1);
1140	    rows.push(row);
1141	    last = { v, row };
1142	  }
1143	  return rows.map(sortKeys);
1144	}
1145	
