1147	
1148	function sortKeys<T extends object>(o: T): T {
1149	  const out: Record<string, unknown> = {};
1150	  for (const k of Object.keys(o).sort()) {
1151	    const v = (o as Record<string, unknown>)[k];
1152	    if (v !== undefined) out[k] = v;
1153	  }
1154	  return out as T;
1155	}
